{
  "approach": "Compute the core funnel as set-membership counts per stage (application_started → document_uploaded → pay_now_clicked → purchase_completed) using metric:funnel_conversion and metric:drop_off_rate, cut by os/device since this is a global question (rule 6c), then drill into the two known-issue hotspots (K1 iOS OTP regression at pay→purchase, cut by app_version/geo; K2 Android passport-capture failures via metric:passport_capture_pass_rate by month) to explain the why behind any drop found. All base-table queries apply duplicate_id IS NULL and is_back_filled != 1 per convention:data_hygiene.", 
  "tasks": [
    {
      "id": "t1",
      "title": "Funnel stage counts by os",
      "question": "For each funnel stage (application_started, document_uploaded, pay_now_clicked, purchase_completed), count uniqExact(application_id) as set membership (no timestamp ordering), applying duplicate_id IS NULL and is_back_filled != 1, broken out by os (bucket NULL/'' as 'unknown') and device_type. This gives funnel_conversion (purchase_completed ÷ application_started) and per-stage step-through/drop-off rates.",
      "tables": ["application_started", "document_uploaded", "pay_now_clicked", "purchase_completed"],
      "dimensions": ["os", "device_type"]
    },
    {
      "id": "t2",
      "title": "K1 check: pay→purchase by app_version/geo",
      "question": "Compute metric:standard_checkout_conversion_rate (purchase_completed ÷ pay_now_clicked application_ids, hygiene filters applied) restricted to os='iOS', broken out by app_version (recent builds) and geoip_country_code (Gulf/AED geos vs rest), to test whether recent iOS builds show a materially lower pay→purchase rate than the ~25-27% flat baseline in coarse cuts (K1 hypothesis).",
      "tables": ["pay_now_clicked", "purchase_completed"],
      "dimensions": ["app_version", "geoip_country_code"],
      "depends_on": "t1"
    },
    {
      "id": "t3",
      "title": "K2 check: capture pass rate by month/os",
      "question": "Compute metric:passport_capture_pass_rate = uniqExact(id) where is_crossed_failed_attempt_threshold=0 ÷ uniqExact(id) total, on document_uploaded, grouped by calendar month and os (with hygiene filters applied), to quantify the Android escalation (K2: 6.0%→33.5% Jan-Jun) versus flat iOS.",
      "tables": ["document_uploaded"],
      "dimensions": ["os", "month"]
    }
  ]
}
